PRAGMA foreign_keys = ON;
CREATE TABLE member (user_id TEXT PRIMARY KEY REFERENCES user(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at INTEGER NOT NULL);
CREATE TABLE capability (user_id TEXT NOT NULL REFERENCES member(user_id), name TEXT NOT NULL CHECK(name IN ('admin','verifier','reviewer:visual','reviewer:portability','reviewer:executable-source','publisher')), PRIMARY KEY(user_id,name));
CREATE TABLE authority_policy (id INTEGER PRIMARY KEY CHECK(id=1), epoch INTEGER NOT NULL DEFAULT 0);
INSERT INTO authority_policy(id,epoch) VALUES(1,0);
CREATE TABLE agent_token (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES member(user_id), label TEXT NOT NULL, secret_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL CHECK(json_valid(scopes)), expires_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE TABLE asset_version (id TEXT PRIMARY KEY CHECK(length(id)=64), asset_id TEXT NOT NULL, contributor_id TEXT NOT NULL REFERENCES member(user_id), title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('preset','static','recipe')), subject TEXT NOT NULL CHECK(json_valid(subject)), state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','submitted','processing','awaiting_review','changes_requested','rejected','approved','published','withdrawn')), review_revision INTEGER NOT NULL DEFAULT 0, approval_policy_epoch INTEGER, approval_review_revision INTEGER, approved_by TEXT REFERENCES member(user_id), created_at INTEGER NOT NULL, published_at INTEGER);
CREATE TABLE version_artifact (version_id TEXT NOT NULL REFERENCES asset_version(id), path TEXT NOT NULL, sha256 TEXT NOT NULL CHECK(length(sha256)=64), bytes INTEGER NOT NULL CHECK(bytes>=0 AND bytes<=2097152), media_type TEXT NOT NULL, uploaded INTEGER NOT NULL DEFAULT 0 CHECK(uploaded IN (0,1)), PRIMARY KEY(version_id,path));
CREATE TABLE technical_attestation (record_id TEXT PRIMARY KEY CHECK(length(record_id)=64), version_id TEXT NOT NULL REFERENCES asset_version(id), reviewer_id TEXT NOT NULL REFERENCES member(user_id), record TEXT NOT NULL CHECK(json_valid(record)), created_at INTEGER NOT NULL);
CREATE TABLE review_record (record_id TEXT PRIMARY KEY CHECK(length(record_id)=64), version_id TEXT NOT NULL REFERENCES asset_version(id), reviewer_id TEXT NOT NULL REFERENCES member(user_id), category TEXT NOT NULL CHECK(category IN ('visual','portability','executable-source')), record TEXT NOT NULL CHECK(json_valid(record)), created_at INTEGER NOT NULL);
CREATE TABLE record_revocation (record_id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES member(user_id), reason TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE review_attachment (owner_id TEXT NOT NULL REFERENCES member(user_id), sha256 TEXT NOT NULL CHECK(length(sha256)=64), bytes INTEGER NOT NULL CHECK(bytes>=0 AND bytes<=2097152), PRIMARY KEY(owner_id,sha256));
CREATE TABLE vote (user_id TEXT NOT NULL REFERENCES member(user_id), asset_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,asset_id));
CREATE TABLE audit_event (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, target TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), created_at INTEGER NOT NULL);
CREATE TABLE local_mail_outbox (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, url TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TRIGGER immutable_version BEFORE UPDATE OF id,asset_id,contributor_id,title,kind,subject,created_at ON asset_version BEGIN SELECT RAISE(ABORT,'immutable_version'); END;
CREATE TRIGGER immutable_artifact BEFORE UPDATE OF version_id,path,sha256,bytes,media_type ON version_artifact BEGIN SELECT RAISE(ABORT,'immutable_artifact'); END;
CREATE TRIGGER no_artifact_delete BEFORE DELETE ON version_artifact BEGIN SELECT RAISE(ABORT,'immutable_artifact'); END;
CREATE TRIGGER artifact_upload_once BEFORE UPDATE OF uploaded ON version_artifact WHEN OLD.uploaded=1 AND NEW.uploaded!=1 BEGIN SELECT RAISE(ABORT,'immutable_upload'); END;
CREATE TRIGGER immutable_technical_update BEFORE UPDATE ON technical_attestation BEGIN SELECT RAISE(ABORT,'immutable_attestation'); END;
CREATE TRIGGER immutable_technical_delete BEFORE DELETE ON technical_attestation BEGIN SELECT RAISE(ABORT,'immutable_attestation'); END;
CREATE TRIGGER immutable_review_update BEFORE UPDATE ON review_record BEGIN SELECT RAISE(ABORT,'immutable_review'); END;
CREATE TRIGGER immutable_review_delete BEFORE DELETE ON review_record BEGIN SELECT RAISE(ABORT,'immutable_review'); END;
CREATE TRIGGER immutable_revocation_update BEFORE UPDATE ON record_revocation BEGIN SELECT RAISE(ABORT,'immutable_revocation'); END;
CREATE TRIGGER immutable_revocation_delete BEFORE DELETE ON record_revocation BEGIN SELECT RAISE(ABORT,'immutable_revocation'); END;
CREATE TRIGGER immutable_audit_update BEFORE UPDATE ON audit_event BEGIN SELECT RAISE(ABORT,'append_only_audit'); END;
CREATE TRIGGER immutable_audit_delete BEFORE DELETE ON audit_event BEGIN SELECT RAISE(ABORT,'append_only_audit'); END;
CREATE TRIGGER role_grant_epoch AFTER INSERT ON capability BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER role_revoke_epoch AFTER DELETE ON capability BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER role_update_epoch AFTER UPDATE ON capability BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER member_status_epoch AFTER UPDATE OF status ON member BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER technical_review_revision AFTER INSERT ON technical_attestation BEGIN UPDATE asset_version SET review_revision=review_revision+1 WHERE id=NEW.version_id; END;
CREATE TRIGGER authored_review_revision AFTER INSERT ON review_record BEGIN UPDATE asset_version SET review_revision=review_revision+1 WHERE id=NEW.version_id; END;
CREATE TRIGGER revocation_epoch AFTER INSERT ON record_revocation BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND (id IN (SELECT version_id FROM technical_attestation WHERE record_id=NEW.record_id) OR id IN (SELECT version_id FROM review_record WHERE record_id=NEW.record_id)); END;
CREATE INDEX published_asset ON asset_version(state,asset_id,published_at);
CREATE INDEX version_author ON asset_version(contributor_id,created_at);
CREATE INDEX technical_version ON technical_attestation(version_id);
CREATE INDEX review_version ON review_record(version_id);
CREATE INDEX token_member ON agent_token(user_id,expires_at);
